<div class="field"><label><?php echo $this->lang('Status') ?></label><select name="settings[status]" class="ui fluid selection dropdown"><option value="all"><?php echo $this->lang('All') ?></option><?php foreach (['registration' => 'Registration', 'running' => 'Running', 'completed' => 'Completed'] as $value => $label): ?><option value="<?php echo $value ?>"<?php if (($settings['status'] ?? '') === $value) echo ' selected'; ?>><?php echo $this->lang($label) ?></option><?php endforeach ?></select></div><div class="field"><label><?php echo $this->lang('Limit') ?></label><input type="number" min="1" max="24" name="settings[limit]" value="<?php echo (int)($settings['limit'] ?? 6) ?>" /></div>
